// Actual fixed Go selector collaborators; never a duplicate selector algorithm.
package main
import("encoding/json";"os";"time";"github.com/livekit/livekit-server/pkg/config";"github.com/livekit/livekit-server/pkg/routing/selector";"github.com/livekit/protocol/livekit")
type Case struct{Name string `json:"name"`;Kind string `json:"kind"`;SortBy string `json:"sort_by"`;Algorithm string `json:"algorithm"`;CPULimit float32 `json:"cpu_limit"`;SysLimit float32 `json:"sysload_limit"`;Region string `json:"region"`;Regions []config.RegionConfig `json:"regions"`;Nodes []*livekit.Node `json:"nodes"`;Ages []int64 `json:"ages"`;TrackLimit int32 `json:"track_limit"`;BytesLimit float32 `json:"bytes_limit"`}
type Result struct{Name string `json:"name"`;Status string `json:"status"`;ID string `json:"selected_id,omitempty"`;Error string `json:"error,omitempty"`;Limits []bool `json:"limits"`;BoundaryAmbiguous bool `json:"clock_boundary_ambiguous"`}
func one(c Case)(r Result){r.Name=c.Name;r.Status="PASS";defer func(){if recover()!=nil{r.Status="PANIC";r.Error="fixed-source nil pointer panic"}}();conf:=config.DefaultConfig;conf.Region=c.Region;conf.NodeSelector=config.NodeSelectorConfig{Kind:c.Kind,SortBy:c.SortBy,Algorithm:c.Algorithm,CPULoadLimit:c.CPULimit,SysloadLimit:c.SysLimit,Regions:c.Regions};conf.Limit.NumTracks=c.TrackLimit;conf.Limit.BytesPerSec=c.BytesLimit;now:=time.Now().Unix();for i,n:=range c.Nodes{if n.Stats!=nil&&i<len(c.Ages){n.Stats.UpdatedAt=now-c.Ages[i]};r.Limits=append(r.Limits,selector.LimitsReached(conf.Limit,n.Stats))};s,err:=selector.CreateNodeSelector(&conf);if err!=nil{r.Status="ERROR";r.Error=err.Error();return};n,err:=s.SelectNode(c.Nodes);r.BoundaryAmbiguous=time.Now().Unix()!=now;if err!=nil{r.Status="ERROR";r.Error=err.Error()}else{r.ID=n.Id};return}
func main(){var cases []Case;if err:=json.NewDecoder(os.Stdin).Decode(&cases);err!=nil{os.Stderr.WriteString("invalid selector fixture input\n");os.Exit(1)};out:=make([]Result,0,len(cases));for _,c:=range cases{out=append(out,one(c))};if err:=json.NewEncoder(os.Stdout).Encode(out);err!=nil{os.Exit(1)}}
